package com.alibaba.cloud.ai.tongyi;

import java.util.List;
import java.util.Objects;

import com.alibaba.dashscope.aigc.generation.models.QwenParam;

import org.springframework.ai.chat.prompt.ChatOptions;

/**
 * The configuration information for the TongYi chat requests.
 *
 * @author <a href="mailto:yuluo08290126@gmail.com">yuluo</a>
 * @author <a href="mailto:xiaozhu0206@qq.com">xiaozhu</a>
 */

public class TongYiChatOptions implements ChatOptions {

	/**
	 * The API key used for authentication with the TongYi service.
	 */
	private String apiKey;

	/**
	 * The specified model name used for the chat requests.
	 */
	private String model = "qwen-turbo";

	/**
	 * The random number seed used when generating, the user controls the randomness of the content generated by the model.
	 */
	private Integer seed = 1234;

	/**
	 * Specifies the maximum number of tokens that the model can generate.
	 */
	private Integer maxTokens = 1500;

	/**
	 * The probability threshold of the nucleus sampling method in the generation process.
	 */
	private Double topP = 0.8;

	/**
	 * The size of the sampling candidate set during generation.
	 */
	private Integer topK;

	/**
	 * Used to control the repeatability during model generation.
	 */
	private Double repetitionPenalty = 1.1;

	/**
	 * Used to control the degree of randomness and diversity.
	 */
	private Double temperature = 0.85;

	/**
	 * The stop parameter is used to implement precise control over the content generation process.
	 */
	private List<Integer> stop;

	/**
	 * Whether to use streaming output.
	 */
	private Boolean stream = false;

	/**
	 * Whether to enable the network search function of the model during the generation process.
	 */
	private Boolean enableSearch = false;

	/**
	 * The format of the returned data, which is "text" by default and can also be "message".
	 */
	private String resultFormat = QwenParam.ResultFormat.MESSAGE;

	/**
	 * Whether to enable incremental output in the streaming output mode.
	 */
	private Boolean incrementalOutput = false;

	/**
	 * A list of tools the model may call.
	 */
	private List<String> tools;

	/**
	 * The system role content used in the chat requests.
	 */
	private String SystemUser = "You are a helpful assistant.";

	public static Builder builder() {

		return new Builder();
	}

	@Override
	public Float getTemperature() {

		return this.temperature.floatValue();
	}

	@Override
	public void setTemperature(Float temperature) {

		this.temperature = temperature.doubleValue();
	}

	@Override
	public Float getTopP() {

		return this.topP.floatValue();
	}

	@Override
	public void setTopP(Float topP) {

		this.topP = topP.doubleValue();
	}

	@Override
	public Integer getTopK() {

		return this.topK;
	}

	@Override
	public void setTopK(Integer topK) {

		this.topK = topK;
	}

	public String getSystemUser() {

		return SystemUser;
	}

	public void setSystemUser(String systemUser) {

		SystemUser = systemUser;
	}

	public String getApiKey() {

		return apiKey;
	}

	public void setApiKey(String apiKey) {

		this.apiKey = apiKey;
